/**
 * Book action button component with AsChildSlot pattern.
 *
 * Loading state flow:
 * 1. User clicks → loading during booking API call
 * 2. Booking completes → onCheckout/onComplete callback is awaited
 * 3. If callback returns navigateToCheckout() → loading stays until navigation
 * 4. If callback returns void → loading stops immediately
 *
 * @example
 * ```tsx
 * // Basic usage - call navigateToCheckout when ready
 * <Booking.Actions.Book
 *   onCheckout={(navigateToCheckout) => navigateToCheckout({ postFlowUrl: '/thank-you' })}
 * />
 *
 * // With callbacks
 * <Booking.Actions.Book
 *   onCheckout={(navigateToCheckout) => navigateToCheckout({ postFlowUrl: '/thank-you' })}
 *   onComplete={({ orderId }) => navigate(`/thank-you?orderId=${orderId}`)}
 *   onError={(error) => console.error(error.message)}
 * />
 *
 * // With render function
 * <Booking.Actions.Book
 *   onCheckout={(navigateToCheckout) => navigateToCheckout({ postFlowUrl: '/thank-you' })}
 *   onComplete={({ orderId }) => navigate(`/thank-you?orderId=${orderId}`)}
 * >
 *   {({ isLoading, error, canBook, onClick, disabled }) => (
 *     <button onClick={onClick} disabled={disabled}>
 *       {isLoading ? <Spinner /> : 'Book Now'}
 *     </button>
 *   )}
 * </Booking.Actions.Book>
 *
 * // With asChild
 * <Booking.Actions.Book
 *   asChild
 *   onCheckout={(navigateToCheckout) => navigateToCheckout({ postFlowUrl: '/thank-you' })}
 *   onComplete={({ orderId }) => navigate(`/thank-you?orderId=${orderId}`)}
 * >
 *   <CustomBookButton />
 * </Booking.Actions.Book>
 * ```
 */
